SELECT DISTINCT bs.id, bs.block_strategy_name, bs.vulnerability_levels, bs.filter_vulnerability_whites, bs.filter_vulnerability_blacks, bs.filter_license_whites, bs.filter_license_blacks, bs.filter_all_package_name, bs.filter_all_license FROM block_strategy bs LEFT JOIN block_strategy_repository bsr ON bs.id = bsr.block_strategy_id LEFT JOIN block_strategy_info bsi ON bs.id = bsi.block_strategy_id
bs.id > 0
AND bs.block_strategy_name = #{blockStrategy.blockStrategyName}
AND bs.block_strategy_name LIKE concat(#{blockStrategy.matchBlockStrategyName}, '%')
AND bsr.storage_id = #{blockStrategy.storageId}
AND bsr.storage_id LIKE concat(#{blockStrategy.matchStorageId}, '%')
AND bsr.repository_id = #{blockStrategy.repositoryId}
AND bsr.repository_id LIKE concat(#{blockStrategy.matchRepositoryId}, '%')
AND bsi.package_name = #{blockStrategy.packageName}
AND bsi.package_name LIKE concat(#{blockStrategy.matchPackageName}, '%')
AND bsi.license_id = #{blockStrategy.licenseId}
AND bsi.license_id LIKE concat(#{blockStrategy.matchLicenseId}, '%')
ORDER BY bs.id

SELECT bs.id, bs.block_strategy_name, bs.vulnerability_levels, bs.filter_vulnerability_whites, bs.filter_vulnerability_blacks, bs.filter_license_whites, bs.filter_license_blacks, bs.filter_all_package_name, bs.filter_all_license, bsi.license_id bsi_license_id, bsi.package_name bsi_package_name FROM block_strategy bs LEFT JOIN block_strategy_repository bsr ON bs.id = bsr.block_strategy_id LEFT JOIN block_strategy_info bsi ON bs.id = bsi.block_strategy_id
bs.id > 0
AND bs.block_strategy_name = #{blockStrategy.blockStrategyName}
AND bs.block_strategy_name LIKE concat(#{blockStrategy.matchBlockStrategyName}, '%')
AND bsr.storage_id = #{blockStrategy.storageId}
AND bsr.storage_id LIKE concat(#{blockStrategy.matchStorageId}, '%')
AND bsr.repository_id = #{blockStrategy.repositoryId}
AND bsr.repository_id LIKE concat(#{blockStrategy.matchRepositoryId}, '%')
AND bsi.package_name = #{blockStrategy.packageName}
AND bsi.package_name LIKE concat(#{blockStrategy.matchPackageName}, '%')
AND bsi.license_id = #{blockStrategy.licenseId}
AND bsi.license_id LIKE concat(#{blockStrategy.matchLicenseId}, '%')
ORDER BY bs.id
